## Business EDA

-- Part 1 — Overall Business Performance

-- Query 1: Total Sales
-- Business Question:
-- What is the company's total sales?

SELECT
ROUND(SUM(SalesAmount),2) AS TotalSales
FROM master_fact_internet_sales;

-- Insight
--   Overall revenue generated by Adventure Works.

-- Query 2: Total Production Cost

SELECT
ROUND(SUM(TotalProductCost),2) AS TotalProductionCost
FROM master_fact_internet_sales;

-- Query 3: Total Profit

SELECT
ROUND(
SUM(SalesAmount)-SUM(TotalProductCost),2
) AS TotalProfit
FROM master_fact_internet_sales;

-- Query 4: Profit Margin %

SELECT
ROUND(
(SUM(SalesAmount)-SUM(TotalProductCost))
/
SUM(SalesAmount)
*100,
2
) AS ProfitMargin
FROM master_fact_internet_sales;

-- Business Insight
-- Higher profit margin = better business performance.

## Query 5: Total Orders

SELECT
COUNT(DISTINCT SalesOrderNumber) AS TotalOrders
FROM master_fact_internet_sales;

## Query 6: Total Customers

SELECT
COUNT(DISTINCT CustomerKey) AS TotalCustomers
FROM master_fact_internet_sales;

## Query 7: Total Products Sold

SELECT
COUNT(DISTINCT ProductKey) AS TotalProducts
FROM master_fact_internet_sales;

## Query 8: Total Quantity Sold

SELECT
SUM(OrderQuantity) AS QuantitySold
FROM master_fact_internet_sales;

-- Query 9: Average Order Value (AOV)

SELECT
ROUND(
SUM(SalesAmount)
/
COUNT(DISTINCT SalesOrderNumber),
2
) AS AverageOrderValue
FROM master_fact_internet_sales;

-- Query 10: Average Selling Price

SELECT
ROUND(
AVG(UnitPrice),
2
) AS AverageSellingPrice
FROM master_fact_internet_sales;


## Executive KPI Dashboard Query
-- Instead of running multiple queries, create one executive summary:

SELECT
ROUND(SUM(SalesAmount),2) AS TotalSales,

ROUND(SUM(TotalProductCost),2) AS ProductionCost,

ROUND(SUM(SalesAmount)-SUM(TotalProductCost),2) AS Profit,

ROUND(
((SUM(SalesAmount)-SUM(TotalProductCost))
/
SUM(SalesAmount))*100,
2
) AS ProfitMargin,

COUNT(DISTINCT SalesOrderNumber) AS Orders,

COUNT(DISTINCT CustomerKey) AS Customers,

COUNT(DISTINCT ProductKey) AS Products,

SUM(OrderQuantity) AS Quantity,

ROUND(
SUM(SalesAmount)
/COUNT(DISTINCT SalesOrderNumber),
2
) AS AverageOrderValue

FROM master_fact_internet_sales;

-- This query produces a one-row KPI summary suitable for an executive dashboard.

## Business Interpretation
-- After running the queries, interpret the results rather than just reporting numbers:

-- Total Sales: Overall revenue generated during the available data period.
-- Production Cost: Total manufacturing cost incurred.
-- Profit: Revenue remaining after production costs.
-- Profit Margin: Efficiency of converting revenue into profit.
-- Average Order Value: Average revenue earned per order.
-- Total Customers: Number of unique customers served.
-- Total Products: Number of unique products sold.
-- Quantity Sold: Total units sold.

-- These are the KPIs executives typically review first.



## Phase 2 – Time Series Analysis

DESCRIBE master_fact_internet_sales;

-- Query 1 – Year-wise Sales
-- Business Question
-- How has sales changed year over year?

SELECT
    d.CalendarYear,
    ROUND(SUM(f.SalesAmount),2) AS TotalSales
FROM master_fact_internet_sales f
JOIN DimDate d
ON f.OrderDateKey = d.DateKey
GROUP BY d.CalendarYear
ORDER BY d.CalendarYear;

-- Insight:
-- Shows business growth over years.
-- Used for KPI cards and yearly trend charts.

## Query 2 – Quarter-wise Sales

SELECT
    CONCAT('Q', d.CalendarQuarter) AS Quarter,
    ROUND(SUM(f.SalesAmount),2) AS TotalSales
FROM master_fact_internet_sales f
JOIN DimDate d
ON f.OrderDateKey = d.DateKey
GROUP BY d.CalendarQuarter
ORDER BY d.CalendarQuarter;

-- Insight
-- Identifies the strongest quarter.


## Query 3 – Month-wise Sales

SELECT
d.MonthNumberOfYear,
d.EnglishMonthName,
ROUND(SUM(f.SalesAmount),2) AS Sales
FROM master_fact_internet_sales f
JOIN DimDate d
ON f.OrderDateKey=d.DateKey
GROUP BY
d.MonthNumberOfYear,
d.EnglishMonthName
ORDER BY d.MonthNumberOfYear;


## Query 4 – Year-Month Trend

SELECT

CONCAT(
d.CalendarYear,
'-',
LEFT(d.EnglishMonthName,3)
) AS YearMonth,

ROUND(SUM(f.SalesAmount),2) AS Sales

FROM master_fact_internet_sales f

JOIN DimDate d
ON f.OrderDateKey=d.DateKey

GROUP BY

d.CalendarYear,
d.MonthNumberOfYear,
d.EnglishMonthName

ORDER BY

d.CalendarYear,
d.MonthNumberOfYear;

## Query 5 – Monthly Production Cost

SELECT
CONCAT(
d.CalendarYear,
'-',
LEFT(d.EnglishMonthName,3)
) AS YearMonth,
ROUND(SUM(f.TotalProductCost),2) AS ProductionCost
FROM master_fact_internet_sales f
JOIN DimDate d
ON f.OrderDateKey=d.DateKey
GROUP BY
d.CalendarYear,
d.MonthNumberOfYear,
d.EnglishMonthName
ORDER BY
d.CalendarYear,
d.MonthNumberOfYear;


## Query 6 – Monthly Profit

SELECT
CONCAT(
d.CalendarYear,
'-',
LEFT(d.EnglishMonthName,3)
) AS YearMonth,
ROUND(SUM(f.Profit),2) AS Profit
FROM master_fact_internet_sales f
JOIN DimDate d
ON f.OrderDateKey=d.DateKey
GROUP BY
d.CalendarYear,
d.MonthNumberOfYear,
d.EnglishMonthName
ORDER BY
d.CalendarYear,
d.MonthNumberOfYear;


-- Query 7 – Monthly Dashboard Dataset
-- This single query provides most of the metrics needed for a dashboard.

SELECT

d.CalendarYear,

d.CalendarQuarter,

d.MonthNumberOfYear,

d.EnglishMonthName,

ROUND(SUM(f.SalesAmount),2) AS Sales,

ROUND(SUM(f.TotalProductCost),2) AS ProductionCost,

ROUND(SUM(f.Profit),2) AS Profit,

ROUND(AVG(f.ProfitMargin),2) AS AvgProfitMargin,

SUM(f.OrderQuantity) AS QuantitySold,

COUNT(DISTINCT f.SalesOrderNumber) AS Orders,

ROUND(AVG(f.UnitPrice),2) AS AvgSellingPrice

FROM master_fact_internet_sales f

JOIN DimDate d
ON f.OrderDateKey=d.DateKey

GROUP BY

d.CalendarYear,
d.CalendarQuarter,
d.MonthNumberOfYear,
d.EnglishMonthName

ORDER BY

d.CalendarYear,
d.MonthNumberOfYear;


## Query 8 – Year-over-Year Sales

SELECT

d.CalendarYear,
ROUND(SUM(f.SalesAmount),2) AS Sales
FROM master_fact_internet_sales f
JOIN DimDate d
ON f.OrderDateKey=d.DateKey
GROUP BY d.CalendarYear
ORDER BY d.CalendarYear;


## Query 9 – Month-over-Month Growth (%)

WITH MonthlySales AS
(
SELECT

d.CalendarYear,

d.MonthNumberOfYear,

CONCAT(
d.CalendarYear,
'-',
LPAD(d.MonthNumberOfYear,2,'0')
) AS YearMonth,

SUM(f.SalesAmount) AS Sales

FROM master_fact_internet_sales f

JOIN DimDate d
ON f.OrderDateKey=d.DateKey

GROUP BY
d.CalendarYear,
d.MonthNumberOfYear
)

SELECT

YearMonth,

ROUND(Sales,2) AS Sales,

ROUND(
(
Sales - LAG(Sales) OVER(ORDER BY YearMonth)
)
/
LAG(Sales) OVER(ORDER BY YearMonth)
*100,
2
) AS GrowthPercent

FROM MonthlySales;

-- This query uses window functions and is excellent for interviews and trend analysis.


## Query 10 – Running Total Sales

WITH MonthlySales AS
(
SELECT

d.CalendarYear,

d.MonthNumberOfYear,

CONCAT(
d.CalendarYear,
'-',
LPAD(d.MonthNumberOfYear,2,'0')
) AS YearMonth,

SUM(f.SalesAmount) AS Sales

FROM master_fact_internet_sales f

JOIN DimDate d
ON f.OrderDateKey=d.DateKey

GROUP BY
d.CalendarYear,
d.MonthNumberOfYear
)

SELECT

YearMonth,

ROUND(Sales,2) AS Sales,

ROUND(
SUM(Sales)
OVER(
ORDER BY YearMonth
),
2
) AS RunningSales

FROM MonthlySales;


## Query 11 – Rolling 3-Month Average

WITH MonthlySales AS
(
SELECT

d.CalendarYear,

d.MonthNumberOfYear,

CONCAT(
d.CalendarYear,
'-',
LPAD(d.MonthNumberOfYear,2,'0')
) AS YearMonth,

SUM(f.SalesAmount) AS Sales

FROM master_fact_internet_sales f

JOIN DimDate d
ON f.OrderDateKey=d.DateKey

GROUP BY
d.CalendarYear,
d.MonthNumberOfYear
)

SELECT

YearMonth,

ROUND(Sales,2) AS Sales,

ROUND(
AVG(Sales)
OVER(
ORDER BY YearMonth
ROWS BETWEEN 2 PRECEDING
AND CURRENT ROW
),
2
) AS Rolling3MonthAvg

FROM MonthlySales;


## Query 12 – Best & Worst Sales Months
-- Top 5 Months

SELECT

CONCAT(
d.CalendarYear,
'-',
LEFT(d.EnglishMonthName,3)
) AS YearMonth,

ROUND(SUM(f.SalesAmount),2) AS Sales

FROM master_fact_internet_sales f

JOIN DimDate d
ON f.OrderDateKey=d.DateKey

GROUP BY
d.CalendarYear,
d.MonthNumberOfYear,
d.EnglishMonthName

ORDER BY Sales DESC

LIMIT 5;

-- Bottom 5 Months

SELECT
CONCAT(
d.CalendarYear,
'-',
LEFT(d.EnglishMonthName,3)
) AS YearMonth,
ROUND(SUM(f.SalesAmount),2) AS Sales
FROM master_fact_internet_sales f
JOIN DimDate d
ON f.OrderDateKey=d.DateKey
GROUP BY
d.CalendarYear,
d.MonthNumberOfYear,
d.EnglishMonthName
ORDER BY Sales ASC
LIMIT 5;